def calculate_S(N, a):
    b = N - a
    # S = a * b * |b - a|
    return a * b * abs(b - a)

N = 11
results = {}
# We only need to check a up to N//2 = 5
for a in range(1, N // 2 + 1):
    S = calculate_S(N, a)
    results[a] = S

print(results)
max_S = max(results.values())
print(f"Maximum S found: {max_S}")
